import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        List<String> simple = Solution.cachedSegments("alpha:beta:gamma");
        check(simple.equals(Arrays.asList("alpha", "beta", "gamma")), "wrong segment order");

        List<String> spaced = Solution.cachedSegments(" left :middle: right ");
        check(spaced.equals(Arrays.asList(" left ", "middle", " right ")), "segment text was not preserved");

        List<String> one = Solution.cachedSegments("single");
        check(one.equals(Arrays.asList("single")), "single segment failed");

        expectUnsupported(new Runnable() { public void run() { simple.add("corrupt"); } });
        expectUnsupported(new Runnable() { public void run() { spaced.set(0, "corrupt"); } });
        List<String> repeated = Solution.cachedSegments("alpha:beta:gamma");
        check(repeated.equals(Arrays.asList("alpha", "beta", "gamma")), "cached value was corrupted");

        expectIAE(new Runnable() { public void run() { Solution.cachedSegments(null); } });
        expectIAE(new Runnable() { public void run() { Solution.cachedSegments(""); } });
        expectIAE(new Runnable() { public void run() { Solution.cachedSegments(" \t "); } });
        expectIAE(new Runnable() { public void run() { Solution.cachedSegments(":a"); } });
        expectIAE(new Runnable() { public void run() { Solution.cachedSegments("a:"); } });
        expectIAE(new Runnable() { public void run() { Solution.cachedSegments("a::b"); } });
        expectIAE(new Runnable() { public void run() { Solution.cachedSegments("a:  :b"); } });
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectIAE(Runnable action) {
        try { action.run(); } catch (IllegalArgumentException expected) { return; }
        throw new AssertionError("Expected IllegalArgumentException");
    }

    private static void expectUnsupported(Runnable action) {
        try { action.run(); } catch (UnsupportedOperationException expected) { return; }
        throw new AssertionError("Expected UnsupportedOperationException");
    }
}

